mod fmt;
mod parse;
mod eval;
mod load;

use std::io::Write;

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let mut inp = String::new();
    let mut out = String::new();
    let mut i = 2;
    while i < args.len() {
        match args[i].as_str() {
            "--in" => { inp = args[i + 1].clone(); i += 2; }
            "--out" => { out = args[i + 1].clone(); i += 2; }
            _ => i += 1,
        }
    }
    let h = std::thread::Builder::new().stack_size(3usize << 30).spawn(move || {
        let wb = load::load(&inp).expect("load");
        let json = eval::run(wb);
        let mut f = std::fs::File::create(&out).expect("create");
        f.write_all(json.as_bytes()).unwrap();
    }).unwrap();
    h.join().unwrap();
}
E
cat > src/load.rs <<'E'
use crate::eval::{V, Er};
use quick_xml::events::Event;
use quick_xml::Reader;
use std::io::Read;
use std::rc::Rc;

pub struct SheetData {
    pub name: String,
    pub cells: Vec<(u32, u32, Cell)>,
}
pub enum Cell {
    Val(V),
    Formula(String),
}
pub struct Workbook {
    pub sheets: Vec<SheetData>,
}

fn read_zip(z: &mut zip::ZipArchive<std::fs::File>, name: &str) -> Option<Vec<u8>> {
    let mut f = z.by_name(name).ok()?;
    let mut v = Vec::new();
    f.read_to_end(&mut v).ok()?;
    Some(v)
}

pub fn parse_ref(s: &str) -> Option<(u32, u32)> {
    let b = s.as_bytes();
    let mut i = 0;
    let mut c: u32 = 0;
    while i < b.len() && b[i].is_ascii_alphabetic() {
        c = c * 26 + (b[i].to_ascii_uppercase() - b'A' + 1) as u32;
        i += 1;
    }
    if i == 0 || i == b.len() { return None; }
    let mut r: u32 = 0;
    while i < b.len() && b[i].is_ascii_digit() { r = r * 10 + (b[i] - b'0') as u32; i += 1; }
    if i != b.len() || r == 0 { return None; }
    Some((r - 1, c - 1))
}

fn attr(e: &quick_xml::events::BytesStart, key: &[u8]) -> Option<String> {
    for a in e.attributes().flatten() {
        if a.key.as_ref() == key {
            return Some(a.unescape_value().ok()?.into_owned());
        }
    }
    None
}

fn parse_shared(data: &[u8]) -> Vec<String> {
    let mut rd = Reader::from_reader(data);
    let mut out = Vec::new();
    let mut buf = Vec::new();
    let mut cur = String::new();
    let mut in_t = false;
    let mut in_si = false;
    loop {
        match rd.read_event_into(&mut buf) {
