                (b'<', b'>') => { self.i += 2; Op::Ne }
                (b'<', b'=') => { self.i += 2; Op::Le }
                (b'>', b'=') => { self.i += 2; Op::Ge }
                (b'<', _) => { self.i += 1; Op::Lt }
                (b'>', _) => { self.i += 1; Op::Gt }
                (b'=', _) => { self.i += 1; Op::Eq }
                _ => return Ok(l),
            };
            let r = self.concat()?;
            l = Node::Bin(op, Box::new(l), Box::new(r));
        }
