// number formatting helpers

pub fn sig15(x: f64) -> (String, i32) {
    // returns digits (no trailing zeros, at least "0") and decimal exponent of first digit
    let s = format!("{:.14e}", x.abs());
    let (m, e) = s.split_once('e').unwrap();
    let e: i32 = e.parse().unwrap();
    let digits: String = m.chars().filter(|c| *c != '.').collect();
    let d = digits.trim_end_matches('0').to_string();
    (if d.is_empty() { "0".into() } else { d }, e)
}

pub fn num_to_str(x: f64) -> String {
    if x == 0.0 { return "0".into(); }
    if !x.is_finite() { return "#NUM!".into(); }
    let (d, e) = sig15(x);
    let mut out = String::new();
    if x < 0.0 { out.push('-'); }
    if e >= 15 || e < -5 {
        out.push_str(&d[..1]);
        if d.len() > 1 { out.push('.'); out.push_str(&d[1..]); }
        out.push('E');
        out.push(if e < 0 { '-' } else { '+' });
        out.push_str(&format!("{:02}", e.abs()));
    } else if e >= 0 {
        let e = e as usize;
        if d.len() <= e + 1 {
            out.push_str(&d);
            for _ in 0..(e + 1 - d.len()) { out.push('0'); }
        } else {
            out.push_str(&d[..e + 1]);
            out.push('.');
            out.push_str(&d[e + 1..]);
        }
    } else {
        out.push_str("0.");
        for _ in 0..(-e - 1) { out.push('0'); }
        out.push_str(&d);
    }
    out
}

pub fn round_half_away(x: f64, dec: i32) -> f64 {
    if !x.is_finite() { return x; }
    if dec > 15 { return x; }
    let f = 10f64.powi(dec.abs());
    let v = if dec >= 0 { x * f } else { x / f };
    if !v.is_finite() { return x; }
    // snap to 15 significant digits to kill representation noise
    let v15: f64 = format!("{:.14e}", v).parse().unwrap_or(v);
    let r = v15.round();
    if dec >= 0 { r / f } else { r * f }
}

fn civil_from_days(z: i64) -> (i64, u32, u32) {
    let z = z + 719468;
    let era = if z >= 0 { z } else { z - 146096 } / 146097;
    let doe = (z - era * 146097) as u64;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let y = yoe as i64 + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = (doy - (153 * mp + 2) / 5 + 1) as u32;
    let m = if mp < 10 { mp + 3 } else { mp - 9 } as u32;
    (if m <= 2 { y + 1 } else { y }, m, d)
}
fn days_from_civil(y: i64, m: u32, d: u32) -> i64 {
    let y = if m <= 2 { y - 1 } else { y };
    let era = if y >= 0 { y } else { y - 399 } / 400;
    let yoe = (y - era * 400) as u64;
    let mp = if m > 2 { m - 3 } else { m + 9 } as u64;
    let doy = (153 * mp + 2) / 5 + d as u64 - 1;
    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    era * 146097 + doe as i64 - 719468
}
