pub fn serial_to_ymd(s: i64) -> (i64, u32, u32) { civil_from_days(s + days_from_civil(1899, 12, 30)) }
pub fn ymd_to_serial(y: i64, m: u32, d: u32) -> i64 { days_from_civil(y, m, d) - days_from_civil(1899, 12, 30) }
