cd /workspace/submission; python3 - <<'E'
p='src/fmt.rs'; s=open(p).read()
a=s.index('pub fn sig15'); b=s.index('pub fn num_to_str')
s=s[:a]+'''pub fn sig15(x: f64) -> (String, i32) {
    // shortest round-trip digits, then round half-up to 15 significant digits
    let s = format!("{:e}", x.abs());
    let (m, e) = s.split_once('e').unwrap();
    let mut e: i32 = e.parse().unwrap();
    let mut digits: Vec<u8> = m.bytes().filter(|c| *c != b'.').map(|c| c - b'0').collect();
    if digits.len() > 15 {
        let up = digits[15] >= 5;
        digits.truncate(15);
        if up {
            let mut i = 14i32;
            loop {
                if i < 0 { digits.insert(0, 1); digits.truncate(15); e += 1; break; }
                if digits[i as usize] == 9 { digits[i as usize] = 0; i -= 1; } else { digits[i as usize] += 1; break; }
            }
        }
    }
    while digits.len() > 1 && *digits.last().unwrap() == 0 { digits.pop(); }
    (digits.iter().map(|d| (b'0' + d) as char).collect(), e)
}

'''+s[b:]
s=s.replace('let v15: f64 = format!("{:.14e}", v).parse().unwrap_or(v);','let v15: f64 = { let (d, e) = sig15(v); format!("{}{}e{}", if v < 0.0 { "-" } else { "" }, format!("{}.{}", &d[..1], if d.len() > 1 { &d[1..] } else { "0" }), e).parse().unwrap_or(v) };')
open(p,'w').write(s)
