s=s.replace('if v.is_empty() { V::N(0.0) } else { V::N(v.iter().rev().product()) } }','if v.is_empty() { V::N(0.0) } else { let mut p = 1.0f64; for x in v.iter().rev() { p *= x; if p.is_infinite() { return Err(Er::Num); } } V::N(p) } }')
open(p,'w').write(s)
